import base64,hashlib,json,pathlib
b=base64.b64decode('')
expected='cbe5d3d3cac517774976f7b68f84f266b7564bae96812f8dde4eed4a60fa9ccb'
assert hashlib.sha256(b).hexdigest()==expected
d=pathlib.Path('/var/tmp/km3-pmp4010-accept-20261019-cbe5d3d3')
d.mkdir(mode=0o700,exist_ok=False)
p=d/'controlled-forward.runner.py'
with p.open('xb') as f:f.write(b)
p.chmod(0o600)
actual=hashlib.sha256(p.read_bytes()).hexdigest()
assert actual==expected
print(json.dumps(dict(path=str(p),bytes=len(b),sha256=actual,verified=True,CAN_socket_opens=0,CAN_sends=0,process_control=0)))
